reference_solution:
def min_eating_speed(piles, h):
    def hours(k):
        return sum((p + k - 1) // k for p in piles)
    left, right = 1, max(piles)
    while left < right:
        mid = (left + right) // 2
        if hours(mid) <= h:
            right = mid
        else:
            left = mid + 1
    return left
